## I18N RULES

```typescript
// mobile/src/i18n/index.ts — CRITICAL PATTERN
import enTranslations from './en.json';
import pidginTranslations from './pidgin.json';

i18n.init({
  resources: { en: { translation: enTranslations }, pidgin: { translation: pidginTranslations } },
  initImmediate: false,  // ← SYNC init — prevents raw key display before first render
  fallbackLng: 'en',
  returnNull: false,
  returnEmptyString: false,
});
// NEVER fetch translations from network — always bundle locally
```

